-- BigNoteBox Help translation -- deDE (ALL-648)
-- Generated by _work/tools/help-i18n.lua merge from a translator's files. Do not
-- edit the fp values; text edits are fine (run `help-i18n.lua check deDE` after).
-- H = help topics and chapter covers ("chapter.<key>"), F = Features tab sections
-- by their English header. fp = the English it was translated from (STALE when
-- that changed). Anything not here shows in English.

if BigNoteBox.GetActiveLanguage() ~= "deDE" then return end

local BNB = BigNoteBox
BNB.HELP_LOCALES    = BNB.HELP_LOCALES or {}
BNB.FEATURE_LOCALES = BNB.FEATURE_LOCALES or {}
local H, F = {}, {}
BNB.HELP_LOCALES.deDE, BNB.FEATURE_LOCALES.deDE = H, F


H["getting-started"] = { fp = "4695e0b7",
    title = "Erste Schritte",
    body = "{p}BigNoteBox ist ein Notizblock direkt im Spiel. Deine Notizen gelten für deinen gesamten Account. Jede Notiz gehört entweder allen Charakteren (global) oder einem einzelnen Charakter.{/p}\n{div:gold-ornate}\n{h3}BigNoteBox öffnen{/h3}\n- Gib /bnb ein, drücke Strg+N oder klicke auf die Minikarten-Schaltfläche {icon:@icon:16}.\n- Mit F8 erstellst du eine neue Notiz, mit F7 eine Schnellnotiz: {link*bnbui:help.quick-notes*Schnellnotizen}.\n- Mit Strg+Leertaste öffnest du die {link*bnbui:help.oracle-search*Oracle-Suche} von überall aus.\n{div:gold-ornate}\n{h3}Notizen finden{/h3}\n{p}Das Hauptfenster zeigt deine Notizen auf zwei Arten an. Mit dem Symbol oben links wechselst du zwischen ihnen:{/p}\n- {icon:@Explorer/ex-explorer-mode:16} Die {link*bnbui:help.explorer-view*Explorer-Ansicht}: Deine Notizen und Ordner erscheinen als Symbolraster im ganzen Fenster, ähnlich dem Datei-Explorer auf deinem Computer.\n- {icon:@Explorer/ex-list-mode:16} Die {link*bnbui:help.note-list*Notizliste}: links eine Liste, rechts die geöffnete Notiz.\n{div:gold-ornate}\n{h3}Schreiben{/h3}\n{p}Öffne eine Notiz und leg los: {link*bnbui:help.writing-notes*Notizen schreiben}. Neue Notizen können mit einer {link*bnbui:help.note-templates*Vorlage} beginnen.{/p}\n{h3}Wähle, was du brauchst{/h3}\n{p}Die meisten Teile von BigNoteBox sind Module, die du ein- und ausschalten kannst: {link*bnbui:help.modules*Module}. Der {link*bnbui:wizard*Einrichtungsassistent} richtet sie für dich ein.{/p}\n{p}{icon:@Documentation/doc-info:16} Für weitere Optionen kannst du fast alles mit der rechten Maustaste anklicken: Notizen, Ordner, Links und leere Flächen.{/p}",
}

H["note-list"] = { fp = "54bd7d47",
    title = "Notizliste",
    body = "{p}Die Liste links im Hauptfenster, neben der geöffneten Notiz. Mit dem Symbol {icon:@Explorer/ex-explorer-mode:16} links neben der Sortierauswahl wechselst du zur {link*bnbui:help.explorer-view*Explorer-Ansicht}. Von oben nach unten:{/p}\n- {icon:@ContextMenu/Symbols/cm-pinned:16} Angeheftet: deine angehefteten Notizen (Rechtsklick > Oben anheften).\n- {icon:@ContextMenu/Symbols/cm-folder:16} Deine Ordner: {link*bnbui:help.folders*Ordner}.\n- Notizen: alle übrigen Notizen in der gewählten Sortierung.\n{div:gold-ornate}\n{h3}Notiz finden{/h3}\n- {icon:@Explorer/ex-search:16} Das Suchfeld findet beim Tippen Text in Titeln und Notizen.\n- {icon:@UI/ui-favorite:16} Die Stern-Schaltfläche zeigt nur Favoriten, die Aufgaben-Schaltfläche {icon:@UI/ui-tasks:16} nur Notizen mit Aufgaben.\n- {icon:@UI/ui-folder:16} Mit den Schaltflächen für die Ordneransicht und den Tag-Baum {icon:@UI/ui-treeview:16} links vom Suchfeld gruppierst du Notizen nach Ordnern oder Tags.\n{div:gold-ornate}\n{h3}Notizen verwalten{/h3}\n- Klicke mit der rechten Maustaste auf eine Notiz, um alle verfügbaren Aktionen zu sehen.\n- Ziehe eine Notiz an eine andere Stelle, um die Reihenfolge zu ändern (benutzerdefinierte Sortierung), oder ziehe sie auf einen Ordner.\n- Mit dem Pfeil oben klappst du die Liste auf Symbole zusammen.\n{p}Die Charakterreiter neben der Liste zeigen jeweils nur die Notizen eines Charakters an: {link*bnbui:settings.modules.sidebar*}.{/p}",
}

H["explorer-view"] = { fp = "f32bcc76",
    title = "Explorer-Ansicht",
    body = "{p}Die Explorer-Ansicht zeigt deine Notizen und Ordner als Symbolraster im gesamten Hauptfenster an, ähnlich wie der Datei-Explorer auf deinem Computer. Mit dem Symbol oben links wechselst du zwischen dieser Ansicht {icon:@Explorer/ex-explorer-mode:16} und der {link*bnbui:help.note-list*Notizliste} {icon:@Explorer/ex-list-mode:16}.{/p}\n{div:gold-ornate}\n{h3}Öffnen und zurückgehen{/h3}\n- Doppelklicke auf eine Notiz oder einen Ordner, um sie zu öffnen.\n- Mit dem Pfeil oben links oder Esc gehst du zurück. Daneben siehst du, wo du dich gerade befindest: Klicke dort auf Notizen, um zur obersten Ebene zurückzukehren.\n- {icon:@Explorer/ex-chevron-down:16} Angeheftet und Notizen sind Überschriften, die du einklappen kannst.\n{h3}Notizen auswählen{/h3}\n- Klicke auf eine Notiz, um sie auszuwählen. Mit Strg+Klick wählst du weitere aus, mit Umschalt+Klick eine Reihe. Du kannst auch einen Auswahlrahmen um mehrere Notizen ziehen.\n- Die Leiste unten zeigt an, wie viele Notizen und Ordner es gibt und wie viele du ausgewählt hast.\n{div:gold-ornate}\n{h3}Die Schaltflächen oben{/h3}\n- {icon:@Explorer/ex-new:16} Neu: eine Notiz {icon:@Explorer/ex-new-note:16} im geöffneten Ordner oder einen neuen Ordner {icon:@Explorer/ex-new-folder:16} erstellen.\n- {icon:@Explorer/ex-copy:16} Kopieren, {icon:@Explorer/ex-move:16} Verschieben, {icon:@Explorer/ex-delete:16} Löschen, {icon:@Explorer/ex-rename:16} Umbenennen, {icon:@Explorer/ex-pin:16} Anheften, {icon:@Explorer/ex-favorite:16} Favorit, {icon:@Explorer/ex-share:16} Teilen und {icon:@Explorer/ex-export:16} Exportieren gelten für die ausgewählten Notizen.\n- {icon:@Explorer/ex-sort:16} Sortieren und Reihenfolge: Hier legst du fest, wie Notizen sortiert werden.\n- {icon:@Explorer/ex-view:16} Ansicht: kleine {icon:@Explorer/ex-view-small:16}, mittlere {icon:@Explorer/ex-view-medium:16} oder große {icon:@Explorer/ex-view-large:16} Symbole, eine Titelliste {icon:@Explorer/ex-view-list:16}, Details in Spalten {icon:@Explorer/ex-view-details:16} oder alle Notizen in einer einzigen Liste {icon:@Explorer/ex-view-flat:16}.\n- {icon:@Explorer/ex-search:16} Die Such-Schaltfläche öffnet ein Suchfeld. Mit den Schaltflächen an dessen Ende zeigst du nur Favoriten oder Notizen mit Aufgaben an.\n- {icon:@Explorer/ex-more:16} In einem kleinen Fenster findest du Schaltflächen, die nicht mehr hineinpassen, unter Mehr.\n{div:gold-ornate}\n{h3}Ziehen und rechtsklicken{/h3}\n- Ziehe Notizen auf einen Ordner, um sie dort abzulegen. Ziehe sie auf Notizen im Pfad, um sie wieder herauszunehmen.\n- {icon:@Explorer/ex-sort-custom:16} Bei benutzerdefinierter Sortierung kannst du die Symbole in die gewünschte Reihenfolge ziehen.\n- Klicke für weitere Aktionen mit der rechten Maustaste auf eine Notiz, einen Ordner oder eine leere Fläche. Auf leeren Flächen findest du unter anderem Sortieren nach, Neuer Ordner und Ansichtsoptionen wie Angeheftete Notizen zuerst und Favoriten zuerst.\n{div:gold-ornate}\n{h3}In einer Notiz{/h3}\n{p}Die Notiz füllt das Fenster aus. Die Schaltfläche ganz rechts in der Werkzeugleiste öffnet das Notizmenü mit Notizeinstellungen {icon:@Toolbar/tb-notesettings:16} und Situationen. Wenn du mit der rechten Maustaste auf den Text klickst, findest du unten Notizeinstellungen öffnen. Mit dem Symbol neben dem Titel änderst du das Notizsymbol.{/p}\n{p}Einstellungen: {link*bnbui:settings.modules.explorer*}. Dort legst du fest, welche Ansicht beim Öffnen des Fensters erscheint und ob die zuletzt geöffnete Notiz wieder angezeigt wird.{/p}",
}

H["folders"] = { fp = "c61e0bba",
    title = "Ordner",
    body = "{p}Ordner halten Notizen zusammen. Sie stehen alphabetisch zwischen Angeheftet und deinen Notizen und merken sich, ob du sie geöffnet gelassen hast.{/p}\n{div:gold-ornate}\n{h3}Notizen in einen Ordner legen{/h3}\n- {icon:@ContextMenu/Symbols/cm-folder:16} Rechtsklick auf eine Notiz > In Ordner verschieben, dann einen Ordner oder {icon:@ContextMenu/Symbols/cm-folder-add:16} Neuer Ordner ... auswählen.\n- Ziehe eine Notiz auf eine Ordnerüberschrift. Ziehe sie auf die Überschrift Notizen, um sie wieder herauszunehmen.\n- {icon:@ContextMenu/Symbols/cm-copy-move:16} Unter Aktionen > Kopieren / Verschieben nach ... kannst du Notizen ebenfalls in einen Ordner kopieren oder verschieben.\n- {icon:@Explorer/ex-new-folder:16} In der {link*bnbui:help.explorer-view*Explorer-Ansicht} kannst du Notizen auf ein Ordnersymbol ziehen oder mehrere auswählen und mit der rechten Maustaste auf eine leere Fläche klicken > Neuer Ordner mit Auswahl.\n{div:gold-ornate}\n{h3}Der Ordner selbst{/h3}\n{p}Klicke mit der rechten Maustaste auf einen Ordner, um eine Notiz hinzuzufügen, ihn umzubenennen, ihm eine Farbe zu geben oder ihn zu löschen. Eine angeheftete Notiz erscheint unter Angeheftet und in ihrem Ordner.{/p}\n{p}{icon:@Documentation/doc-info:16} Beim Löschen eines Ordners werden seine Notizen nie gelöscht: Sie erscheinen wieder unter Notizen.{/p}\n{p}Einstellungen: {link*bnbui:settings.modules.folders*}.{/p}",
}

H["tags"] = { fp = "5f86da8a",
    title = "Tags",
    body = "{p}Tags sind kurze Begriffe für eine Notiz, etwa Schlachtzug oder Gold. Eine Notiz kann beliebig viele Tags haben; bei Tags spielt Groß- und Kleinschreibung keine Rolle.{/p}\n- {icon:@ContextMenu/Symbols/cm-tags-add:16} Rechtsklick auf eine Notiz > Tags hinzufügen, oder füge sie im Editor unter dem Titel hinzu.\n- Klicke auf ein Tag, um nur die Notizen mit diesem Tag anzuzeigen.\n- {icon:@UI/ui-treeview:16} Die Tag-Baum-Schaltfläche gruppiert alle Notizen nach Tags.\n- {icon:@Topbar/Normal/tp-tagmanager-normal:16} Mit {link*bnbui:tagmanager*} kannst du Tags in all deinen Notizen umbenennen, einfärben und löschen.",
}

H["oracle-search"] = { fp = "239e530d",
    title = "Oracle-Suche",
    body = "{p}Eine Suchleiste, mit der du von überall im Spiel Notizen anhand ihres Titels, Textes oder ihrer Tags findest. Öffne sie mit Strg+Leertaste oder /bnb search.{/p}\n{div:gold-ornate}\n{h3}Notiz öffnen{/h3}\n- Eingabetaste: Notiz öffnen.\n- Umschalttaste: als Haftnotiz {icon:@ContextMenu/Symbols/cm-sticky-note:16}. Strg: im Fokusmodus {icon:@ContextMenu/Symbols/cm-focus-mode:16}. Alt: in der Referenzbox {icon:@ContextMenu/Symbols/cm-reference-box:16}.\n{div:gold-ornate}\n{h3}Suche eingrenzen{/h3}\n{p}Gib vor deinen Suchbegriffen einen Buchstaben und ein Leerzeichen ein. Gib ? in die Leiste ein, um alle Kürzel zu sehen.{/p}\n- s Spielernotizen, n NPC-Notizen {icon:@Search/s-icon-npc:16}, i Notizen mit einem Gegenstand {icon:@Search/s-icon-items:16}, z Notizen zu einem Gebiet {icon:@Search/s-icon-situation:16}.\n- c dieser Charakter, g global {icon:@Search/s-icon-global:16}, a Aufgaben {icon:@Search/s-icon-tasks:16}, e Alarme {icon:@Search/s-icon-alarm:16}, x formatierte Notizen {icon:@Search/s-icon-rich:16}, l einfache Notizen.\n- d heute, d woche, d monat: in diesem Zeitraum erstellt oder bearbeitet.\n- p durchsucht den Papierkorb, o die Einstellungen, v sendet eine Notiz an den Chat.\n- #tag, @Person, um die es in der Notiz geht, * Favoriten, -Wort schließt ein Wort aus, \"ein genauer Wortlaut\".\n{p}Einstellungen: {link*bnbui:settings.modules.oracle*}.{/p}",
}

H["writing-notes"] = { fp = "661d8ac2",
    title = "Notizen schreiben",
    body = "{p}Der Editor zeigt die geöffnete Notiz: oben den Titel, darunter den Text. In der Notizliste nimmt er die rechte Fensterhälfte ein; in der Explorer-Ansicht füllt die Notiz das Fenster aus.{/p}\n- Notizen werden beim Tippen gespeichert. In den Einstellungen kannst du stattdessen eine Speichern-Schaltfläche aktivieren.\n- {icon:@Toolbar/tb-undo:16} Rückgängig und {icon:@Toolbar/tb-redo:16} Wiederholen funktionieren für jede Notiz einzeln: {link*bnbui:help.history-and-undo*Verlauf und Rückgängig}.\n- {icon:@ContextMenu/Symbols/cm-locked:16} Eine gesperrte Notiz lässt sich nicht ändern: Rechtsklick > Notiz sperren / Notiz entsperren.\n- Über die Werkzeugleiste oberhalb des Textes fügst du Wegpunkte {icon:@Toolbar/tb-way:16}, Links {icon:@Toolbar/tb-link:16}, Zeitstempel {icon:@Toolbar/tb-timestamp:16} und {link*bnbui:help.note-tokens*Notiz-Tokens} {icon:@Toolbar/tb-syntax:16} ein.\n- Die Schaltfläche ganz rechts in der Werkzeugleiste öffnet das Notizmenü: Notizeinstellungen, Situationen, Alarme, Aufgaben und mehr.\n- Klicke mit der rechten Maustaste auf den Text, um Spielinformationen einzufügen. Ganz unten findest du Notizeinstellungen öffnen.\n- {icon:@Toolbar/tb-notesettings:16} In den Notizeinstellungen legst du Aussehen, Symbol und Situation der Notiz fest.\n{p}{icon:@ContextMenu/Symbols/cm-rich-note:16} Für Überschriften, Farben und Bilder machst du daraus eine {link*bnbui:help.rich-notes*formatierte Notiz}.{/p}",
}

H["note-templates"] = { fp = "6931bb8a",
    title = "Notizvorlagen",
    body = "{p}Eine Vorlage füllt eine neue Notiz mit einem Titel, Text, Tags und einem Ausgangsdesign.{/p}\n{p:c}{icon:@Templates/tmp-blank:40} {icon:@Templates/tmp-boss:40} {icon:@Templates/tmp-weekly:40} {icon:@Templates/tmp-diary:40} {icon:@Templates/tmp-more:40}{/p}\n- Im Fenster Neue Notiz stehen oben Leer, Boss, Wöchentlich und Tagebuch. Unter Mehr findest du alle Vorlagen.\n- {icon:@ContextMenu/Symbols/cm-save-template:16} So erstellst du eine eigene Vorlage: Rechtsklick auf eine Notiz > Aktionen > Als Vorlage speichern.\n- {icon:@ContextMenu/Symbols/cm-share:16} Vorlagen lassen sich wie Notizen per Code teilen.\n{p}Unter {link*bnbui:settings.notes.templates*} kannst du deine Vorlagen umbenennen, ändern oder löschen und integrierte Vorlagen kopieren.{/p}",
}

H["rich-notes"] = { fp = "c32bd228",
    title = "Formatierte Notizen",
    body = "{p}Eine formatierte Notiz ist wie eine kleine Seite: mit Überschriften, Farben, Symbolen, Bildern und Links. Über die Werkzeugleiste fügst du die Tags ein; die Vorschau neben dem Editor zeigt dir beim Tippen das Ergebnis.{/p}\n{p}Rechtsklick auf eine Notiz > In formatierte oder einfache Notiz umwandeln.{/p}\n{div:gold-ornate}\n{h3}Die Tags{/h3}\n- {code}{h1}Title{/h1}{/code}, {code}{h2}...{/h2}{/code}, {code}{h3}...{/h3}{/code}: Überschriften. {code}{h1:c}{/code} zentriert sie, {code}{h1:r}{/code} richtet sie rechts aus.\n- {code}{p}text{/p}{/code}: ein Absatz. {code}{p:c}{/code} zentriert, {code}{p:r}{/code} rechtsbündig.\n- {code}{col:ff8800}text{/col}{/code}: {col:ff8800}farbiger Text{/col}.\n- {code}{u}text{/u}{/code}: {u}unterstrichener Text{/u}. {code}{s}text{/s}{/code}: {s}durchgestrichener Text{/s}. Die Linien erscheinen im Ansichtsmodus und in der Vorschau; beim Bearbeiten siehst du die Tags.\n- {code}{icon:INV_Misc_Note_01:16}{/code}: ein Spielsymbol im Text {icon:INV_Misc_Note_01:16}, 16 Pixel groß.\n- {code}{img:path:width:height}{/code}: ein Bild.\n- {code}{div:name}{/code}: eine Trennlinie über die Breite der Notiz, in einer eigenen Zeile. Über die Schaltfläche Trennlinien in der Werkzeugleiste kannst du eine auswählen.\n- {code}{atlas:name:24}{/code}: eine Spielgrafik anhand ihres Atlasnamens, 24 Pixel hoch. Mit {code}{atlas:name:24:48}{/code} legst du auch die Breite fest. Hänge {code}:c{/code} oder {code}:r{/code} an, um sie in einer eigenen Zeile zentriert oder rechtsbündig anzuzeigen. Atlasnamen findest du mit einem Addon wie TextureAtlasViewer oder einem Programm wie {link*https://github.com/Kruithne/wow.export*wow.export} auf GitHub.\n- {code}{link*address*text}{/code}: ein Link. {code}{link*bnbui:oracle*{icon:INV_Misc_Spyglass_03:16}}{/code} ist eine Bildschaltfläche, die die Oracle-Leiste öffnet: {link*bnbui:oracle*{icon:INV_Misc_Spyglass_03:16}}\n- {code}{br}{/code}: eine neue Zeile innerhalb eines Absatzes.\n- {code}{code}{/code}text{col:9fd0ff}{/code}{/col}: zeigt Text mit allen Tags genau so an, wie er eingegeben wurde, wie in den Beispielen auf dieser Seite.\n{div:gold-ornate}\n{p}Ist das Modul für formatierte Notizen ausgeschaltet, erscheinen alle Notizen als einfacher Text mit sichtbaren Tags ({link*bnbui:settings.modules*}).{/p}",
}

H["note-tokens"] = { fp = "44189bad",
    title = "Notiz-Tokens",
    body = "{p}Ein Notiz-Token ist ein Wort in doppelten geschweiften Klammern, das BigNoteBox für dich ersetzt. Gib {code}{{{/code} in einer Notiz ein, um die Liste zu sehen, oder nutze die Token-Schaltfläche in der Werkzeugleiste.{/p}\n{div:gold-ornate}\n{h3}Hier und jetzt{/h3}\n{p}Wird einmalig ersetzt, sobald du die Eingabe abgeschlossen hast:{/p}\n- {code}{{date}}{/code}, {code}{{time}}{/code}, {code}{{datetime}}{/code}: heutiges Datum und Uhrzeit.\n- {code}{{zone}}{/code}, {code}{{subzone}}{/code}, {code}{{instance}}{/code}: dein Aufenthaltsort.\n- {code}{{target}}{/code}: der Name deines Ziels. {code}{{coords}}{/code}: dein Standort als Wegpunkt-Link.\n{div:gold-ornate}\n{h3}Dein Charakter{/h3}\n{p}{code}{{me}}{/code}, {code}{{name}}{/code}, {code}{{realm}}{/code}, {code}{{class}}{/code}, {code}{{race}}{/code}, {code}{{level}}{/code}, {code}{{spec}}{/code}, {code}{{ilvl}}{/code}, {code}{{guild}}{/code}, {code}{{gold}}{/code} und mehr. In einer formatierten Notiz bleiben sie erhalten und zeigen die Daten des Charakters an, der sie gerade liest, zum Beispiel: {{me}}. In einer einfachen Notiz werden sie sofort durch den jeweiligen Wert ersetzt.{/p}\n{div:gold-ornate}\n{h3}Spieldaten{/h3}\n{p}Per ID: {code}{{item:6948}}{/code} und ähnliche Tokens zeigen den entsprechenden Link an: {{item:6948}}. Die ID ist die Zahl in der Wowhead-Adresse des jeweiligen Objekts.{/p}\n{p}Eigene Tokens erstellen: {link*bnbui:settings.notes.tokens*}.{/p}",
}

H["links-in-notes"] = { fp = "bf5fa15f",
    title = "Links in Notizen",
    body = "{p}Mit der Link-Schaltfläche {icon:@Toolbar/tb-link:16} in der Werkzeugleiste des Editors fügst du an der Cursorposition einen Link ein. Klicke für weitere Optionen mit der rechten Maustaste auf einen Link.{/p}\n{div:gold-ornate}\n{h3}Notiz-Links{/h3}\n{p}Ein Link zu einer anderen Notiz. Er funktioniert auch dann noch, wenn die Notiz umbenannt wird. Wird die Notiz gelöscht, erscheint der Link grau. Klicke mit gedrückter Umschalttaste darauf, um die Notiz aus dem Papierkorb wiederherzustellen.{/p}\n{div:gold-ornate}\n{h3}Wegpunkt-Links{/h3}\n{p}{icon:@Toolbar/tb-way:16} Ein Ort auf der Karte.{/p}\n- Klick: Wegpunkt setzen und verfolgen.\n- Umschalt+Klick: Kartenmarkierung im Chat teilen.\n- Strg+Klick: eine /way-Zeile kopieren.\n- Alt+Klick: Ort auf der Karte anzeigen.\n{p}In einer formatierten Notiz wird eine eingegebene /way-Zeile automatisch zum Link.{/p}\n{div:gold-ornate}\n{h3}BigNoteBox-Links{/h3}\n{p}Über den BigNoteBox-Reiter der Link-Schaltfläche kannst du auf eine Einstellungsseite, ein Fenster oder ein Hilfethema wie dieses verlinken: {link*bnbui:settings.modules.situations*}. In einer formatierten Notiz kannst du daraus eine Bildschaltfläche machen: {link*bnbui:oracle*{icon:INV_Misc_Spyglass_03:20}} (siehe {link*bnbui:help.rich-notes*Formatierte Notizen}).{/p}",
}

H["quick-notes"] = { fp = "f144381a",
    title = "Schnellnotizen",
    body = "{p}{icon:@Explorer/ex-quick-note:16} So erstellst du im Handumdrehen eine Notiz.{/p}\n- Mit F7 erstellst du sofort eine neue Notiz, entweder im Hauptfenster oder als beschreibbare Haftnotiz.\n- {icon:@UI/ui-icon-quest:16} Quest-, Gesprächs-, Buch- und Brieffenster erhalten eine Notiz-Schaltfläche. Ein Klick erstellt eine Notiz mit ihrem Inhalt.\n- {icon:@BCB/addon-dialogueui:16} Dialogue UI und {icon:@BCB/addon-immersion:16} Immersion erhalten dieselbe Schaltfläche.\n{p}Einstellungen: {link*bnbui:settings.modules.quickNote*}.{/p}",
}

H["focus-mode"] = { fp = "c9d2bde8",
    title = "Fokusmodus",
    body = "{p}{icon:@ContextMenu/Symbols/cm-focus-mode:16} Schreibe im Vollbildmodus. Die Spieloberfläche wird ausgeblendet, während sich die Kamera langsam um deinen Charakter dreht.{/p}\n- Öffne ihn über die Werkzeugleiste des Editors oder mit Strg+Eingabetaste in der Oracle-Leiste.\n- Bei formatierten Notizen erscheint die Vorschau neben dem Text.\n- Mit Esc oder der Schließen-Schaltfläche kehrt alles zum vorherigen Zustand zurück.\n{p}Einstellungen: {link*bnbui:settings.modules.focus*}.{/p}",
}

H["spelling"] = { fp = "ce5f9803",
    title = "Rechtschreibung",
    body = "{p}BigNoteBox kann beim Schreiben Wörter, die nicht im Wörterbuch stehen, rot gewellt unterstreichen. Es ändert nie ein Wort für dich: Du entscheidest selbst, was du korrigierst.{/p}\n{div:gold-ornate}\n{h3}Aktivieren{/h3}\n- Unter {link*bnbui:settings.modules.spelling*} findest du den Schalter. Wenn dein Spiel auf Englisch eingestellt ist, ist die Funktion standardmäßig aktiviert.\n- Sprache: Englisch (USA) oder Englisch (Großbritannien). Beide Wörterbücher sind im Addon enthalten.\n- Zeitpunkt der Prüfung: während der Eingabe oder erst, wenn du in der Formatierungsleiste auf Rechtschreibung prüfen {icon:@Toolbar/tb-spellcheck:16} klickst.\n{div:gold-ornate}\n{h3}Was nicht geprüft wird{/h3}\n- Namen: Wörter mit großem Anfangsbuchstaben mitten im Satz, etwa Namen von Bossen, Gebieten oder Spielern. Schalte Namen überspringen aus, um sie ebenfalls zu prüfen. Das erste Wort eines Satzes oder einer Zeile wird immer geprüft.\n- Links, Symbole, Markup und Tokens, Web- und E-Mail-Adressen sowie Zeilen, die mit / beginnen.\n- Wörter in Großbuchstaben (LFG, DPS), Wörter mit Zahlen und Wörter, die nicht in lateinischer Schrift geschrieben sind.\n- Klassennamen, deine eigenen Charaktere und deine Tags gelten als bekannte Wörter, ebenso Spielbegriffe wie Aggro und DPS.\n{div:gold-ornate}\n{h3}Lange Notizen{/h3}\n{p}Notizen mit mehr als 20000 Zeichen werden nur geprüft, wenn du auf Rechtschreibung prüfen klickst. So bleibt das Tippen flüssig. Änderst du den Text, verschwinden die Markierungen; klicke erneut, um ihn noch einmal zu prüfen.{/p}\n{p}{icon:@Documentation/doc-info:16} Die Linien werden über den Text gezeichnet, nicht in ihn eingefügt: In deinen Notizen werden keine Rechtschreibmarkierungen gespeichert.{/p}",
}

H["note-appearance"] = { fp = "72c0f718",
    title = "Aussehen von Notizen",
    body = "{p}Jede Notiz kann ein eigenes Aussehen haben. Öffne die Notizeinstellungen {icon:@Toolbar/tb-notesettings:16} über das Notizmenü ganz rechts in der Werkzeugleiste oder per Rechtsklick auf den Text > Notizeinstellungen öffnen.{/p}\n{div:gold-ornate}\n{h3}Allgemein{/h3}\n- Oben anheften, Als Favorit markieren, Sperren und Formatierte Notiz.\n- Titelfarbe: So erscheint der Titel in der Notizliste.\n- Schriftart und Schriftgröße: Der Text der Notiz im Editor. Du kannst die Schriftart auch über die Werkzeugleiste auswählen.\n{div:gold-ornate}\n{h3}Aussehen{/h3}\n- Textausrichtung und Schriftumriss.\n- Rahmen: ein Rahmen um das Notizsymbol oder ein einfacher Rand mit eigener Größe, eigenem Versatz und eigener Helligkeit.\n- Symbol: Wähle eines der Spielsymbole oder klicke auf Zufällig.\n- Die Vorschau zeigt das Symbol so, wie es in der Notizliste erscheint.\n{p}Im dritten Reiter, Situation, legst du fest, wo die Notiz von selbst erscheint: {link*bnbui:help.situations*Situationen}.{/p}",
}

H["tl-dr"] = { fp = "3ce407b3",
    title = "Kurzfassung",
    body = "{p}Eine Kurzfassung beschreibt eine Notiz in einer einzigen kurzen Zeile, etwa KOS oder Verkauft Materialien. Trage sie im Kurzfassungsfeld über dem Titel oder unter Notizeinstellungen > Situation ein. Wähle einen Textbaustein aus der Liste oder schreibe einen eigenen.{/p}\n{div:gold-ornate}\n{h3}Wo sie erscheint{/h3}\n- Über dem Notiztitel im Hauptfenster, mit einer Schaltfläche zum Hinzufügen oder Ändern.\n- Im Spiel-Tooltip des Spielers oder NPCs, auf den sich die Notiz bezieht: {link*bnbui:help.player-and-npc-notes*Spieler- und NPC-Notizen}.\n- In der Benachrichtigung der Notiz, wenn sie erscheint: {link*bnbui:help.toasts*Benachrichtigungen}.\n{p}Unter {link*bnbui:settings.modules.tldr*} gibt es für jeden dieser Orte ein Kontrollkästchen sowie die Liste der Textbausteine. Du kannst sie ändern, eigene hinzufügen oder die Standardtexte wiederherstellen. Dort schaltest du auch das kleine Feld ein und aus, das beim Zeigen auf eine Notiz in der Notizliste ihre Kurzfassung, ihren Alarm, ihre Situationen und ihre Wegpunkte anzeigt.{/p}\n{p}{icon:@Documentation/doc-info:16} Wenn du Kurzfassungen ausschaltest, werden sie überall ausgeblendet. Deine Einträge bleiben in den Notizen erhalten.{/p}",
}

H["sticky-notes"] = { fp = "eab25011",
    title = "Haftnotizen",
    body = "{p}Eine Haftnotiz ist eine Notiz, die als kleines Fenster auf deinem Bildschirm bleibt, während du spielst.{/p}\n- {icon:@ContextMenu/Symbols/cm-sticky-note:16} Rechtsklick auf eine Notiz > Als Haftnotiz öffnen.\n- Ziehe die Notiz, um sie zu verschieben. Ziehe an einer Kante oder Ecke, um ihre Größe zu ändern.\n- Jede Haftnotiz hat eine eigene Schriftart, Schriftgröße, Farbe, einen eigenen Hintergrund und Rahmen.\n- Formatierte Notizen erscheinen auch als Haftnotiz mit ihrer Formatierung.\n- {icon:@UI/ui-tasks:16} Eine Notiz mit Aufgaben kann statt ihres Textes ihre Aufgaben anzeigen.\n- Nach einem Neuladen erscheinen die Haftnotizen wieder an ihrer letzten Position.\n{p}{icon:@Documentation/doc-info:16} Mit Strg+H blendest du alle Haftnotizen ein oder aus, mit Strg+J holst du sie in den Vordergrund.{/p}\n{p}Einstellungen: {link*bnbui:settings.modules.stickies*}.{/p}",
}

H["situations"] = { fp = "6cfbaa3a",
    title = "Situationen",
    body = "{p}{icon:@UI/ui-situation:16} Durch eine Situation erscheint eine Notiz automatisch dort, wo sie wichtig ist: als {link*bnbui:help.toasts*Benachrichtigung} oder als Haftnotiz.{/p}\n{div:gold-ornate}\n{h3}Mögliche Auslöser{/h3}\n- Ein Gebiet, Untergebiet oder eine Instanz.\n- Ein Instanztyp: Dungeon, Schlachtzug, Tiefe oder Schlachtfeld.\n- Ein Spieler, NPC oder eine Gilde.\n- Ein Fenster: Händler, Bank, Briefkasten, Auktionshaus oder Lehrer.\n- Der Status Ausgeruht oder der Aufenthalt in einem Gasthaus oder einer Stadt.\n{div:gold-ornate}\n{h3}Situation einrichten{/h3}\n{p}{icon:@ContextMenu/Symbols/cm-create-situation:16} Rechtsklick auf eine Notiz > Situation erstellen oder Notizeinstellungen > Situation. Wenn du nichts eingibst, verwendet Hinzufügen deinen aktuellen Aufenthaltsort oder dein Ziel. Wähle dann, wann die Notiz erscheint (zu Beginn, am Ende oder beides) und wie oft {icon:@UI/ui-repeat:16} (jedes Mal, einmal pro Sitzung, einmal täglich, einmal pro Zurücksetzung oder nur einmal). Eine Situation kann auch Wegpunkte setzen.{/p}\n{p}Einstellungen: {link*bnbui:settings.modules.situations*}.{/p}",
}

H["toasts"] = { fp = "5130c164",
    title = "Benachrichtigungen",
    body = "{p}Benachrichtigungen sind kleine Einblendungen auf deinem Bildschirm. Sie erscheinen, wenn die Situation einer Notiz eintritt, Aufgaben zurückgesetzt werden oder ein Update erfolgt ist.{/p}\n- Klicke auf eine Benachrichtigung, um die zugehörige Notiz zu öffnen.\n- Du bestimmst, welche Arten angezeigt werden, wo sie erscheinen, wie sie aussehen und wie lange sie sichtbar bleiben.\n{p}{icon:@Documentation/doc-info:16} Ist das Modul ausgeschaltet, erscheint nichts auf dem Bildschirm. Notizen reagieren aber weiterhin auf die festgelegten Situationen: {link*bnbui:settings.modules.toasts*}.{/p}",
}

H["tasks"] = { fp = "bd882e75",
    title = "Aufgaben",
    body = "{p}{icon:@UI/ui-tasks:16} Aufgaben bilden eine Checkliste innerhalb einer Notiz und können Unteraufgaben haben.{/p}\n- {icon:@ContextMenu/Symbols/cm-create-task:16} Rechtsklick auf eine Notiz > Aufgabe erstellen, oder füge Aufgaben im Aufgabenbereich neben der Notiz hinzu.\n- Hake erledigte Aufgaben ab. Ziehe Aufgaben, um ihre Reihenfolge zu ändern.\n- {icon:@UI/ui-reset:16} Beim täglichen oder wöchentlichen Zurücksetzen können die Häkchen automatisch entfernt werden, entweder für die ganze Liste oder für einzelne Aufgaben. Praktisch für tägliche und wöchentliche Erledigungen.\n- Eine Haftnotiz kann die Aufgaben einer Notiz anzeigen; du kannst sie auch dort abhaken.\n- {icon:@UI/ui-tasks:16} Die Aufgaben-Schaltfläche über der Liste zeigt nur Notizen mit Aufgaben an.\n{p}Einstellungen: {link*bnbui:settings.modules.tasks*}.{/p}",
}

H["alarms"] = { fp = "f34a3fc1",
    title = "Alarme",
    body = "{p}Ein Alarm für eine Notiz wird zu einer von dir festgelegten Zeit ausgelöst: zu einer Uhrzeit in der realen Welt, zu einer Spielzeit oder beim täglichen oder wöchentlichen Zurücksetzen. Er kann einmalig oder an ausgewählten Tagen wiederholt ertönen.{/p}\n- {icon:@ContextMenu/Symbols/cm-create-alarm:16} Rechtsklick auf eine Notiz > Alarm erstellen, oder nutze die Alarm-Schaltfläche {icon:@Toolbar/tb-alarm:16} in der Werkzeugleiste.\n- Wenn der Alarm ausgelöst wird, erscheint die Notiz mit einem Ton. Du kannst ihn später erneut erinnern lassen oder schließen.\n- {icon:@Topbar/Normal/tp-alarms-normal:16} Die Alarm-Schaltfläche oben im Hauptfenster zeigt alle Alarme an.\n{p}Einstellungen: {link*bnbui:settings.modules.alarms*}.{/p}",
}

H["reference-box"] = { fp = "7da86c2b",
    title = "Referenzbox",
    body = "{p}{icon:@ContextMenu/Symbols/cm-reference-box:16} Die Referenzbox ist ein Bereich neben dem Editor für Gegenstände, Zauber, Quests und Links, die du an eine Notiz anhängst.{/p}\n- Ziehe einen Gegenstand oder Zauber hinein oder klicke bei geöffneter Referenzbox mit gedrückter Umschalttaste auf einen Link.\n- Zeige auf einen Eintrag, um seinen Tooltip zu sehen.\n- {icon:@Toolbar/tb-refbox:16} Mit der Referenzbox-Schaltfläche in der Werkzeugleiste fügst du einen Eintrag in den Text ein.\n- {icon:@ContextMenu/Symbols/cm-model-view:16} Bei Notizen über Spieler wird hier ihre Ausrüstung gespeichert. Im Modellbetrachter kannst du sie dir ansehen.\n{p}Einstellungen: {link*bnbui:settings.modules.refBox*}.{/p}",
}

H["player-and-npc-notes"] = { fp = "fe680352",
    title = "Spieler- und NPC-Notizen",
    body = "{p}Erstelle eine Notiz über einen Spieler oder NPC, deren Details automatisch eingetragen werden.{/p}\n- Spieler: über das Betrachten-Fenster oder ihr Rechtsklickmenü.\n- {icon:@Search/s-icon-npc:16} NPC: Nimm ihn ins Ziel und drücke F6 (Notiz aus Ziel erstellen).\n- Die Notiz erhält ein Porträt und weitere Details; bei Spielern wird zudem ihre Ausrüstung in der {link*bnbui:help.reference-box*Referenzbox} gespeichert.\n- {icon:@UI/ui-tldr-add:16} Gib der Notiz eine Kurzfassung, etwa KOS. Sie erscheint im Spiel-Tooltip, wenn du auf den Spieler oder NPC zeigst.\n{p}Einstellungen: {link*bnbui:settings.modules.unitNotes*} und {link*bnbui:settings.modules.tldr*}.{/p}",
}

H["working-with-other-addons"] = { fp = "e9cbcd18",
    title = "Zusammenarbeit mit anderen Addons",
    body = "{p}Diese Addons funktionieren sofort nach der Installation mit BigNoteBox, ohne weitere Einrichtung. Unter {link*bnbui:settings.advanced.integrations*} siehst du, welche davon bei dir installiert sind.{/p}\n{div:gold-ornate}\n{h3}{link*https://www.curseforge.com/wow/addons/bigchatbox*BigChatBox}{/h3}\n- Sende eine Notiz Zeile für Zeile an einen beliebigen Chatkanal oder bearbeite sie vor dem Senden im mehrzeiligen Eingabefeld von BigChatBox.\n- Geteilte Notizen lassen sich ebenfalls über BigChatBox senden.\n- Rechtsklick auf das Chatfeld von BigChatBox > In BigNoteBox speichern erstellt eine Notiz aus deinem eingegebenen Text.\n{div:gold-ornate}\n{h3}Wegpunkte{/h3}\n- {link*https://www.curseforge.com/wow/addons/tomtom*TomTom}: Wegpunkte aus deinen Notizen werden an TomTom übertragen, auch mehrere gleichzeitig. Der Pfeil zeigt auf den ersten.\n- {link*https://www.curseforge.com/wow/addons/mappinenhanced*MapPinEnhanced}: benannte Kartenmarkierungen in einer BigNoteBox-Gruppe, auch mehrere gleichzeitig.\n- {link*https://www.curseforge.com/wow/addons/waypointui*WaypointUI}: jeweils ein Wegpunkt über die Kartenmarkierung des Spiels, mit Pfeil und Entfernungsanzeige.\n{p}Wegpunkte einer Situation können wieder entfernt werden, wenn du den Ort verlässt: {link*bnbui:help.situations*Situationen}.{/p}\n{div:gold-ornate}\n{h3}Quest- und Gesprächstexte{/h3}\n- {link*https://www.curseforge.com/wow/addons/dialogueui*DialogueUI}: Die Schaltfläche Text kopieren erstellt eine Notiz zum Gespräch; Questbelohnungen landen in der Referenzbox. Das funktioniert auch mit Büchern.\n- {link*https://www.curseforge.com/wow/addons/immersion*Immersion}: Während eines Gesprächs erscheint eine kleine Schaltfläche zum Erfassen einer Notiz. Klicke darauf, um eine Notiz zu erstellen.\n{p}Beide Integrationen lassen sich unter {link*bnbui:settings.modules.quickNote*} ein- und ausschalten.{/p}",
}

H["history-and-undo"] = { fp = "d8f69211",
    title = "Verlauf und Rückgängig",
    body = "{p}BigNoteBox bewahrt frühere Versionen deiner Notizen auf.{/p}\n- {icon:@Toolbar/tb-history:16} Verlauf: Beim Ausloggen oder Neuladen wird von jeder Notiz eine Version gespeichert. Vergleiche zwei Versionen nebeneinander und stelle eine ältere wieder her (Rechtsklick > Verlauf).\n- {icon:@Toolbar/tb-restore:16} Wiederherstellungspunkt: Speichere vor einer größeren Änderung selbst einen Zwischenstand.\n- {icon:@Toolbar/tb-undo:16} Rückgängig: Schritte werden für jede Notiz einzeln gespeichert und können sitzungsübergreifend erhalten bleiben.\n- {icon:@ContextMenu/Symbols/cm-restore-auto:16} Rettung: Eine Notiz, die verschwunden ist, ohne gelöscht worden zu sein, lässt sich aus ihrem Verlauf wiederherstellen.\n{p}{icon:@Documentation/doc-important:16} Für den Verlauf und sitzungsübergreifendes Rückgängig wird das Addon BigNoteBox_History benötigt, das mit BigNoteBox geliefert wird. Einstellungen: {link*bnbui:settings.modules.history*} und {link*bnbui:settings.modules.undo*}.{/p}",
}

H["trash"] = { fp = "7861c5eb",
    title = "Papierkorb",
    body = "{p}{icon:@ContextMenu/Symbols/cm-trash:16} Gelöschte Notizen landen zunächst für 30 Tage im Papierkorb, sofern du die Dauer nicht änderst. So kannst du sie wiederherstellen.{/p}\n- {icon:@Topbar/Normal/tp-trash-normal:16} Öffne {link*bnbui:trash*}, um eine Notiz wiederherzustellen oder endgültig zu löschen.\n- Notizen, die länger als die eingestellte Anzahl von Tagen im Papierkorb liegen, werden automatisch entfernt.\n- Mit dem Präfix p durchsucht die Oracle-Suche den Papierkorb.\n{p}{icon:@Documentation/doc-important:16} Ist das Modul ausgeschaltet, werden Notizen sofort endgültig gelöscht: {link*bnbui:settings.modules.trash*}.{/p}",
}

H["backup-and-import"] = { fp = "bc775d97",
    title = "Sicherung und Import",
    body = "{p}Mit {link*bnbui:settings.backup*} sicherst du deine Notizen außerhalb des Spiels.{/p}\n- {icon:@ContextMenu/Symbols/cm-export-json:16} Vollständige Sicherung: alles als JSON – deine Notizen, Vorlagen, Notiz-Tokens, Tag-Farben und sämtliche Einstellungsprofile.\n- Einstellungssicherung: sämtliche Einstellungsprofile, ohne Notizen.\n- {icon:@ContextMenu/Symbols/cm-export-markdown:16} Auswahlweise Sicherung: Wähle Format und Inhalt selbst. Markdown eignet sich zum Lesen außerhalb von WoW.\n{p}Kopiere den Text und speichere ihn in einer Datei. Um ihn wiederherzustellen, füge ihn auf derselben Seite unter Import ein. Dort kannst du auch geteilte Notizen sowie Vorlagen- und Profilcodes importieren.{/p}\n{p}{icon:@Documentation/doc-info:16} Notizen aus anderen Notiz-Addons kannst du ebenfalls unter {link*bnbui:settings.backup*} übernehmen.{/p}",
}

H["sharing-notes"] = { fp = "1e3f9c43",
    title = "Notizen teilen",
    body = "{p}{icon:@ContextMenu/Symbols/cm-share:16} Rechtsklick auf eine Notiz > Notiz teilen.{/p}\n- Wähle aus, was mitgesendet wird: Tags, Aufgaben, Referenzbox, Aussehen, Situation sowie Spieler- oder NPC-Daten.\n- Sende die Notiz direkt an einen anderen Spieler mit BigNoteBox oder kopiere einen Freigabecode, den er unter Import {icon:@Topbar/Normal/tp-import-normal:16} einfügen kann.\n- {icon:@ContextMenu/Symbols/cm-send-chat:16} An Chat senden veröffentlicht den Notiztext Zeile für Zeile in einem Chatkanal.",
}

H["moving-from-another-notes-addon"] = { fp = "0c58a105",
    title = "Von einem anderen Notiz-Addon wechseln",
    body = "{p}Du kannst Notizen aus einem anderen Notiz-Addon nach BigNoteBox kopieren. Die Notizen im ursprünglichen Addon bleiben unverändert.{/p}\n{p}Unter {link*bnbui:settings.backup*} siehst du alle installierten Addons, aus denen BigNoteBox Notizen übernehmen kann.{/p}\n\n{div:gold-ornate}\n\n{h2}Unterstützt ab Version 2.0{/h2}\n  - Noteworthy II\n  - TakeANote\n  - Yet Another Notepad\n  - Notepad\n  - Notes\n  - TinyPad\n  - PurpleNotes\n  - SimpleNote\n  - QuickNotes\n  - OneWoW Notes\n  - MyNotepad\n  - AmmeNotepad.\n\n{div:gold-ornate}\n\n{h2}Hinweis{/h2}\n- Die Vorschau zeigt vor dem Kopieren, welche Notizen übernommen werden.\n- Jetzt migrieren kopiert die Notizen und lädt anschließend die Benutzeroberfläche neu.\n- TakeANote: Seine Kategorien können als Tags für die Notizen übernommen werden.\n- Charaktergebundene Notizen werden für den Charakter übernommen, mit dem du gerade eingeloggt bist. Logge dich mit jedem Charakter ein, um auch dessen Notizen zu übertragen.\n\n{p}Wenn BigNoteBox beim Einloggen eines dieser Addons findet, bietet es dir an, die Notizen zu kopieren. Nicht erneut fragen unterdrückt dieses Angebot; die Schaltfläche auf der Sicherungsseite bleibt verfügbar.{/p}\n{p}{icon:@Documentation/doc-info:16} Wenn du bereits Notizen hast, bietet BigNoteBox dir an, zuerst eine Sicherung zu erstellen: {link*bnbui:help.backup-and-import*Sicherung und Import}.{/p}",
}

H["settings-profiles"] = { fp = "b51820e9",
    title = "Einstellungsprofile",
    body = "{p}{icon:@Topbar/Normal/tp-settings-normal:16} Ein Profil enthält Einstellungen und die Fensteranordnung. Jeder Charakter wählt ein Profil; deine Notizen sind in allen Profilen dieselben.{/p}\n- Erstelle ein neues Profil als Kopie des aktuellen oder beginne ganz von vorn.\n- Exportiere ein Profil als Code, um es zu teilen oder aufzubewahren; importiere ein Profil aus einem Code.\n{p}{icon:@Documentation/doc-important:16} Beim Wechsel zu einem anderen Profil wird die Benutzeroberfläche neu geladen.{/p}\n{p}Einstellungen: {link*bnbui:settings.advanced*}.{/p}",
}

H["modules"] = { fp = "1975dae1",
    title = "Module",
    body = "{p}Die meisten Teile von BigNoteBox sind Module, die du unter {link*bnbui:settings.modules*} ein- und ausschalten kannst. Wenn du ein Modul ausschaltest, wird es überall ausgeblendet. Alles, was zu diesem Modul gehört, bleibt in deinen Notizen erhalten und erscheint wieder, sobald du es einschaltest.{/p}\n{p:c}{icon:@UI/ui-mode-minimal:64} {icon:@UI/ui-mode-full:64} {icon:@UI/ui-mode-custom:64}{/p}\n{p}Mit Minimal, Vollständig und Benutzerdefiniert oben auf dieser Seite schaltest du viele Module gleichzeitig um. Der {link*bnbui:wizard*Einrichtungsassistent} fragt dich beim ersten Einloggen ebenfalls danach.{/p}",
}

H["keys-and-commands"] = { fp = "a13dd004",
    title = "Tasten und Befehle",
    body = "{h3}Tasten{/h3}\n- Strg+N: BigNoteBox öffnen oder schließen.\n- F8: neue Notiz. F7: Schnellnotiz. F6: Notiz über dein Ziel.\n- Strg+Leertaste: Oracle-Suche.\n- Strg+H: alle Haftnotizen ein- oder ausblenden. Strg+J: Haftnotizen in den Vordergrund holen.\n{p}{icon:@Documentation/doc-info:16} Tasten, die das Spiel oder ein anderes Addon bereits verwendet, bleiben unangetastet. Ändere die Tastenbelegung unter {link*bnbui:settings.general*}.{/p}\n{div:gold-ornate}\n{h3}Befehle{/h3}\n- /bnb: Fenster öffnen oder schließen.\n- /bnb new: neue Notiz.\n- /bnb search text: Oracle-Suche.\n- /bnb config: Einstellungen.\n- /bnb whatsnew: neueste Patchnotes.\n- /bnb help: dieses Hilfebuch.\n- /bnb commands: alle Befehle im Chat anzeigen.",
}

H["look-and-feel"] = { fp = "da8d2c5d",
    title = "Darstellung",
    body = "{p}BigNoteBox bietet zwei Erscheinungsbilder: die normale Ansicht mit den spielinternen Fensterrahmen und den Skin-Modus mit einem eigenen dunklen Fenster in den Farben einer Skin-Vorlage. Beide stellst du unter {link*bnbui:settings.appearance*} ein.{/p}\n{div:gold-ornate}\n{h3}Skin-Modus{/h3}\n- Aktiviere Skin-Modus aktivieren und lade die Benutzeroberfläche neu, wenn du dazu aufgefordert wirst.\n- Wähle eine Skin-Vorlage und stelle deren Helligkeit und die Deckkraft des Fensters ein.\n- Design zufällig auswählen gibt dir bei jedem Einloggen oder Neuladen eine neue Vorlage.\n{div:gold-ornate}\n{h3}Text{/h3}\n- Notizschriftart und Schriftgröße des Notiztexts ändern den Text deiner Notizen.\n- Wähle WoWs Standardschriftart, wenn deine Notizen auf Chinesisch oder Koreanisch sind: Die anderen Schriftarten enthalten diese Schriftzeichen nicht.\n- LibSharedMedia-Schriftarten laden fügt die Schriftarten deiner anderen Addons zur Liste hinzu.\n{h3}Notizliste und Datumsangaben{/h3}\n- Anzeigemodus der Notizliste: Normal, Kompakt (kleine Symbole, keine Vorschau) oder Geräumig (große Symbole, drei Vorschauzeilen).\n- Zeitstempelformat: relativ (vor 2 Tagen) oder als Datum. Du kannst auch eine 24-Stunden-Anzeige und statt deiner Ortszeit die Serverzeit wählen.\n{div:gold-ornate}\n{h3}Animation{/h3}\n{p}Unter {link*bnbui:settings.modules.accessibility*} stellst du ein, wie sich Haftnotizen bewegen, wenn du alle ein- oder ausblendest: wie lange die Animation dauert, wie stark sie sich beim Ausblenden vergrößern und wie der Text verblasst. Schalte das Modul aus, wenn du keine Animation möchtest.{/p}",
}

H["right-click-menu"] = { fp = "3eafb8a0",
    title = "Rechtsklickmenü",
    body = "{p}Klicke mit der rechten Maustaste auf eine Notiz, um ihr Menü zu öffnen. Wenn du den Mauszeiger auf einem Haupteintrag wie Kopieren oder Teilen ruhen lässt, öffnet sich ein Untermenü.{/p}\n{p}Unter {link*bnbui:settings.modules.contextMenu*} legst du fest, was ein Klick auf einen Haupteintrag bewirkt:{/p}\n- Wähle einen Eintrag aus seinem Untermenü: Ein Klick auf den Haupteintrag führt diese Aktion aus, und der Haupteintrag übernimmt ihren Namen.\n- Oder wähle Nur Untermenü öffnen.\n{p}Öffnungsverzögerung legt fest, wie lange der Mauszeiger auf einem Eintrag ruhen muss, bevor sich dessen Untermenü öffnet. Ausprobieren öffnet ein Beispielmenü mit deinen Einstellungen; seine Einträge bewirken nichts.{/p}",
}

H["glossary"] = { fp = "e8f26d63",
    title = "Glossar",
    body = "{p}Die Begriffe von BigNoteBox von A bis Z. Klicke auf einen Begriff, um das Hilfethema mit allen Einzelheiten zu öffnen.{/p}\n{h3}A{/h3}\n- {link*bnbui:settings.modules.accessibility*Barrierefreiheit}: Einstellungen für Bewegungen: wie Haftnotizen beim Ein- und Ausblenden bewegt werden und sanftes Scrollen.\n- {link*bnbui:help.alarms*Alarm}: Eine für eine Notiz festgelegte Uhrzeit. Wenn sie erreicht ist, erscheint die Notiz mit einem Ton. Der Alarm kann einmal oder an ausgewählten Tagen wiederholt ertönen.\n{h3}B{/h3}\n- {link*bnbui:help.working-with-other-addons*BigChatBox}: Ein Chat-Addon vom selben Autor. Damit kannst du Notizen Zeile für Zeile in den Chat senden oder eingegebenen Text als Notiz speichern.\n{h3}C{/h3}\n- {link*bnbui:help.getting-started*Charakternotiz}: Eine Notiz, die nur einem Charakter gehört. Das Gegenstück ist eine globale Notiz.\n- {link*bnbui:help.note-list*Eigene Sortierung}: Eine von dir durch Ziehen festgelegte Reihenfolge der Notizen.\n{h3}D{/h3}\n- {col:ffd200}Gefahrenzone{/col}: Das Fenster für umfassende Zurücksetzungen und Löschvorgänge: Einstellungen, Papierkorb, Verlauf, alle Notizen, Wörterbucheinträge, Textkürzel oder alles auf einmal. Vor jedem Vorgang läuft ein Countdown ab.\n- {link*bnbui:help.spelling*Wörterbuch}: Deine eigenen Wörter, die du über das Rechtsklickmenü eines rot markierten Wortes hinzufügst, damit die Rechtschreibprüfung sie akzeptiert.\n{h3}E{/h3}\n- {link*bnbui:help.explorer-view*Explorer-Ansicht}: Deine Notizen und Ordner als Symbolraster im gesamten Hauptfenster, ähnlich dem Datei-Explorer auf deinem Computer.\n- {link*bnbui:help.backup-and-import*Export}: Speichert Notizen außerhalb des Spiels: als JSON zum späteren Importieren, als Markdown zum Lesen oder eine Notiz als Webseite.\n{h3}F{/h3}\n- {link*bnbui:help.note-list*Favorit}: Eine mit einem Stern markierte Notiz. In der Explorer-Ansicht können Favoriten zuerst angezeigt werden, und die Oracle-Suche findet sie mit *.\n- {link*bnbui:features*Funktionen}: Der Reiter im Hilfebuch mit allen Funktionen von BigNoteBox von A bis Z.\n- {link*bnbui:help.sticky-notes*Fokusansicht}: Eine Haftnotiz, bei der außer Text und Hintergrund alles ausgeblendet ist.\n- {link*bnbui:help.focus-mode*Fokusmodus}: Schreiben im Vollbildmodus, während die Spieloberfläche ausgeblendet ist und sich die Kamera langsam um deinen Charakter dreht.\n- {link*bnbui:help.folders*Ordner}: Ein Ort, an dem Notizen in der Notizliste und der Explorer-Ansicht zusammengehalten werden. Beim Löschen eines Ordners werden seine Notizen nie gelöscht.\n- {link*bnbui:help.backup-and-import*Vollständige Sicherung}: Alles in einem JSON-Text: Notizen, Vorlagen, Tokens, Tag-Farben und sämtliche Einstellungsprofile.\n{h3}G{/h3}\n- {link*bnbui:help.getting-started*Globale Notiz}: Eine Notiz, die alle Charaktere deines Accounts sehen. Das Gegenstück ist eine Charakternotiz.\n{h3}H{/h3}\n- {col:ffd200}Hilfebuch{/col}: Dieses Fenster mit Hilfethemen, dem Reiter „Funktionen“ und den Patchnotes. Öffne es über die Schaltfläche „Hilfe“ oben oder mit /bnb help.\n- {link*bnbui:help.history-and-undo*Verlauf}: Frühere Versionen einer Notiz, die beim Ausloggen oder Neuladen gespeichert werden. Du kannst zwei Versionen vergleichen und eine wiederherstellen.\n{h3}I{/h3}\n- {link*bnbui:help.note-appearance*Symbolrahmen}: Der Rahmen um das Symbol einer Notiz, etwa die runde Glaskugel bei Spielernotizen.\n- {link*bnbui:help.backup-and-import*Import}: Importiert eine Sicherung, eine geteilte Notiz, einen Vorlagencode oder einen Profilcode. Die Daten werden zu deinen vorhandenen hinzugefügt und überschreiben sie nie.\n{h3}L{/h3}\n- {link*bnbui:help.writing-notes*Gesperrte Notiz}: Eine Notiz, die erst wieder geändert werden kann, wenn du sie entsperrst.\n{h3}M{/h3}\n- {link*bnbui:help.rich-notes*Formatierung}: Die Tags, mit denen eine formatierte Notiz geschrieben wird, etwa für Überschriften, Farben, Symbole und Links. Der Reiter „Formatierung“ zeigt sie an; die Werkzeugleiste fügt sie für dich ein.\n- {link*bnbui:help.modules*Minimal, Vollständig und Benutzerdefiniert}: Die drei Optionen oben unter Einstellungen > Module, mit denen du viele Module gleichzeitig ein- oder ausschaltest.\n- {link*bnbui:help.getting-started*Minikarten-Schaltfläche}: Die BigNoteBox-Schaltfläche auf der Minikarte: Klicken zum Öffnen, Ziehen zum Verschieben.\n- {link*bnbui:help.reference-box*Modellbetrachter}: Die 3D-Ansicht eines Spielers oder NPCs im Referenzbereich, mit einer Transmog-Ansicht für Spielerausrüstung.\n- {link*bnbui:help.modules*Modul}: Ein Teil von BigNoteBox, den du ein- oder ausschalten kannst. Ist er ausgeschaltet, wird er ausgeblendet; alle zugehörigen Daten bleiben in deinen Notizen erhalten.\n- {link*bnbui:help.moving-from-another-notes-addon*Notizen übernehmen}: Deine Notizen aus einem anderen Notiz-Addon nach BigNoteBox kopieren. Im anderen Addon wird nichts entfernt.\n{h3}N{/h3}\n- {col:ffd200}NEU{/col}: Die grüne Markierung in den Einstellungen für alles, was in dieser Version neu ist.\n- {link*bnbui:help.quick-notes*Notiz erfassen}: Die Notiz-Schaltfläche in Quest-, Dialog-, Buch- und Brieffenstern: Ein Klick speichert den Text als Notiz.\n- {link*bnbui:help.links-in-notes*Notizlink}: Ein Link in einer Notiz, der eine andere Notiz öffnet. Er funktioniert auch noch, wenn diese Notiz umbenannt wird.\n- {link*bnbui:help.note-list*Notizliste}: Die Liste deiner Notizen links im Hauptfenster.\n- {link*bnbui:help.note-appearance*Notizeinstellungen}: Das individuelle Aussehen einer Notiz: Symbol, Symbolrahmen, Rand, Hintergrund und Schriftart sowie ihre Situation.\n- {link*bnbui:help.note-tokens*Notiz-Token}: Ein Wort in doppelten geschweiften Klammern, das BigNoteBox für dich ausfüllt: Datum, Zone, Charaktername und mehr.\n- {link*bnbui:help.player-and-npc-notes*NPC-Notiz}: Eine Notiz über einen NPC, die du erstellst, indem du ihn ins Ziel nimmst und F6 drückst. Sie erhält das Porträt des NPCs.\n{h3}O{/h3}\n- {link*bnbui:help.oracle-search*Oracle-Suche}: Die Suchleiste, mit der du von überall im Spiel aus jede Notiz finden kannst (Strg+Leertaste).\n{h3}P{/h3}\n- {link*bnbui:whatsnew*Patchnotes}: Die Änderungen in jeder Version von BigNoteBox, als Reiter im Hilfebuch.\n- {link*bnbui:help.note-list*Angeheftete Notiz}: Eine Notiz, die ganz oben in der Liste bleibt.\n- {link*bnbui:help.player-and-npc-notes*Spielernotiz}: Eine Notiz über einen Spieler, erstellt über das Betrachten-Fenster oder sein Rechtsklickmenü. Seine Ausrüstung wird darin gespeichert.\n- {link*bnbui:help.oracle-search*Präfix}: Ein Buchstabe vor deinen Suchbegriffen in der Oracle-Leiste, der die Suche eingrenzt, etwa s für Spielernotizen oder a für Aufgaben.\n- {link*bnbui:help.settings-profiles*Profil}: Eine Sammlung von Einstellungen und Fensterpositionen. Jeder Charakter wählt eines; deine Notizen sind in allen Profilen dieselben.\n{h3}Q{/h3}\n- {link*bnbui:help.quick-notes*Schnellnotiz}: Eine mit F7 schnell erstellte Notiz, im Hauptfenster oder als Haftnotiz.\n{h3}R{/h3}\n- {link*bnbui:help.reference-box*Referenzbereich}: Der Bereich neben einer Notiz für Gegenstände, Zauber, Quests und Links, die du ihr hinzufügst.\n- {link*bnbui:help.history-and-undo*Rettung}: Stellt eine verschwundene, aber nicht gelöschte Notiz aus ihrem letzten bekannten Zustand wieder her.\n- {link*bnbui:help.tasks*Zurücksetzung}: Die tägliche und wöchentliche Zurücksetzung des Spiels. Dabei können Aufgaben automatisch abgehakt werden und Alarme ertönen.\n- {link*bnbui:help.history-and-undo*Wiederherstellungspunkt}: Eine Version einer Notiz, die du vor einer größeren Änderung manuell speicherst.\n- {link*bnbui:help.rich-notes*Formatierte Notiz}: Eine Notiz mit Überschriften, Farben, Symbolen, Bildern und Links, die wie eine kleine Seite angezeigt wird.\n- {link*bnbui:help.right-click-menu*Rechtsklickmenü}: Alle Aktionen für eine Notiz, aufrufbar per Rechtsklick. Du bestimmst, was ein Klick auf einen Haupteintrag bewirkt.\n{h3}S{/h3}\n- {link*bnbui:help.getting-started*Geltungsbereich}: Ob eine Notiz global ist oder einem einzelnen Charakter gehört.\n- {link*bnbui:help.sharing-notes*An Chat senden}: Sendet den Text einer Notiz Zeile für Zeile in einen Chatkanal.\n- {link*bnbui:help.backup-and-import*Einstellungssicherung}: Alle Einstellungsprofile als ein JSON-Text, ohne Notizen.\n- {link*bnbui:help.modules*Einrichtungsassistent}: Die Fragen bei deiner ersten Anmeldung, mit denen du Module und Aussehen auswählst.\n- {link*bnbui:help.sharing-notes*Freigabecode}: Eine als Text verpackte Notiz, die du einem anderen Spieler geben kannst. Er fügt den Code unter „Import“ ein.\n- {link*bnbui:help.situations*Situation}: Wo oder wann eine Notiz von selbst erscheint: in einer Zone oder Instanz, bei einem Spieler oder NPC, an einem Händler- oder Bankfenster, wenn du ausgeruht bist und mehr.\n- {link*bnbui:help.look-and-feel*Skin-Modus}: Das zweite Erscheinungsbild von BigNoteBox: ein eigenes dunkles Fenster in den Farben einer Skin-Vorlage.\n- {link*bnbui:settings.modules.accessibility*Sanftes Scrollen}: Das Mausrad scrollt fließend statt sprunghaft. Geschwindigkeit und Distanz kannst du selbst einstellen.\n- {link*bnbui:help.alarms*Schlummern}: Verschiebt einen klingelnden Alarm um eine Weile.\n- {link*bnbui:help.spelling*Rechtschreibprüfung}: Markiert unbekannte Wörter während der Eingabe mit einer roten Linie; per Rechtsklick erhältst du Vorschläge.\n- {link*bnbui:help.sticky-notes*Haftnotiz}: Eine als kleines Fenster auf dem Bildschirm angeheftete Notiz, die beim Spielen sichtbar bleibt.\n- {link*bnbui:help.tasks*Teilaufgabe}: Eine Aufgabe innerhalb einer anderen Aufgabe.\n{h3}T{/h3}\n- {link*bnbui:help.tags*Tag}: Ein kurzes Stichwort an einer Notiz, etwa Raid oder Gold, mit dem du Notizen finden und gruppieren kannst.\n- {link*bnbui:help.tags*Tag-Verwaltung}: Das Fenster, in dem du Tags für alle deine Notizen umbenennen, einfärben und löschen kannst.\n- {link*bnbui:help.tags*Tag-Baum}: Alle Notizen nach Tags gruppiert, mit einem Zweig pro Tag.\n- {link*bnbui:help.tasks*Aufgabe}: Eine Zeile in der Aufgabenliste einer Notiz. Hake sie ab, wenn sie erledigt ist.\n- {link*bnbui:help.note-templates*Vorlage}: Ein vorbereiteter Ausgangspunkt für eine neue Notiz: Titel, Text, Tags und Aussehen.\n- {link*bnbui:help.spelling*Textkürzel}: Ein kurzes Wort, das beim Tippen zu einem längeren Text wird, etwa brb zu be right back.\n- {link*bnbui:help.tl-dr*tl;dr}: Eine kurze Zeile über eine Notiz, etwa KOS oder Verkauft Mats, die unter ihrem Titel und in Tooltips angezeigt wird.\n- {link*bnbui:help.toasts*Toast}: Eine kleine Einblendung auf dem Bildschirm: eine Notiz für eine passende Situation, eine zurückgesetzte Aufgabe oder ein Update.\n- {link*bnbui:help.trash*Papierkorb}: Hier bleiben gelöschte Notizen 30 Tage lang, sofern du die Dauer nicht änderst, damit du sie wiederherstellen kannst.\n{h3}U{/h3}\n- {link*bnbui:help.history-and-undo*Rückgängig}: Macht Änderungen an einer Notiz schrittweise rückgängig. Die Schritte können zwischen Sitzungen erhalten bleiben.\n{h3}V{/h3}\n- {link*bnbui:help.rich-notes*Ansichtsmodus}: Zeigt eine formatierte Notiz als Seite an. Im Bearbeitungsmodus siehst du ihre Formatierung und kannst sie ändern.\n{h3}W{/h3}\n- {link*bnbui:help.links-in-notes*Wegpunkt}: Eine Markierung für einen Ort auf der Karte. Notizen enthalten Wegpunkte als Links, und eine Situation kann sie für dich setzen.",
}

H["chapter.finding-your-notes"] = { fp = "80399eb8",
    name = "Notizen finden",
    body = "{p}Wo deine Notizen zu finden sind und wie du sie wieder aufrufst: Notizliste, Explorer-Ansicht, Ordner, Tags und Oracle-Suche.{/p}",
}

H["chapter.writing"] = { fp = "ec7b83dd",
    name = "Schreiben",
    body = "{p}Alles rund um den Text: Schreiben und Speichern, Vorlagen als Ausgangspunkt, formatierte Notizen mit Überschriften und Farben, automatisch ausgefüllte Tokens und Links zwischen Notizen.{/p}",
}

H["chapter.reminders"] = { fp = "f2fd93f4",
    name = "Erinnerungen",
    body = "{p}Notizen, die von selbst erscheinen: Haftnotizen auf deinem Bildschirm, Notizen am passenden Ort, Toasts, Aufgaben und Alarme.{/p}",
}

H["chapter.in-the-world"] = { fp = "dc764345",
    name = "In der Spielwelt",
    body = "{p}Notizen über das, was du vor dir hast: der Referenzbereich für Gegenstände, Quests und Links sowie Notizen über Spieler und NPCs.{/p}",
}

H["chapter.keeping-notes-safe"] = { fp = "eacf0b07",
    name = "Notizen sichern",
    body = "{p}Nichts muss verloren gehen: Rückgängig und Verlauf, Papierkorb, Sicherungen und das Teilen von Notizen mit anderen Spielern.{/p}",
}

H["chapter.setting-up"] = { fp = "420834f9",
    name = "Einrichtung",
    body = "{p}Passe BigNoteBox an deine Wünsche an: Schalte Module ein oder aus, verwalte Einstellungsprofile und lerne die Tastenkürzel und Chatbefehle kennen.{/p}",
}

F["Notes & Folders"] = { fp = "761da50a",
    header = "Notizen & Ordner",
    blurb = "BigNoteBox ist ein vollwertiger Notizblock in World of Warcraft. Deine Notizen werden für deinen gesamten Account gespeichert: Jede gehört entweder allen Charakteren (global) oder nur einem. Funktioniert mit Retail und WoW: Forever sowie als Beta mit Classic Era, TBC Anniversary und Mists of Pandaria Classic.",
    items = {
        "Beliebig viele Notizen, jeweils mit Titel und so viel Text, wie du möchtest",
        "Für jede Notiz einzeln festlegen, ob sie global oder charakterspezifisch ist",
        "Ordner: Notizen hineinziehen und Ordnern eine Farbe geben; beim Löschen eines Ordners werden seine Notizen nie gelöscht",
        "Notizen oben anheften, als Favoriten markieren oder vor Änderungen sperren",
        "Nach Erstellungsdatum, letzter Änderung, Titel oder einer selbst durch Ziehen festgelegten Reihenfolge sortieren",
        "Notizen duplizieren, kopieren oder verschieben – einzeln oder mehrere gleichzeitig im Auswahlmodus",
        "Per Rechtsklick auf eine Notiz alle verfügbaren Aktionen aufrufen",
    },
}

F["Note List & Explorer View"] = { fp = "c06754f9",
    header = "Notizliste & Explorer-Ansicht",
    blurb = "Zwei Arten, deine Notizen anzusehen. Die Notizliste steht neben der geöffneten Notiz; die Explorer-Ansicht zeigt Notizen und Ordner als Symbolraster im gesamten Fenster an, ähnlich dem Datei-Explorer auf deinem Computer. Mit der ersten Schaltfläche der Werkzeugleiste wechselst du zwischen beiden.",
    items = {
        "Notizliste: Bereiche für angeheftete Notizen, Ordner und Notizen, die sich jeweils merken, ob sie aufgeklappt sind",
        "Explorer-Ansicht: Mehrere Notizen auswählen und auf einen Ordner ziehen",
        "Explorer-Ansicht: Über das Menü „Ansicht“ angeheftete Notizen oder Favoriten zuerst anzeigen",
        "Die Explorer-Ansicht kann bei der zuletzt geöffneten Notiz starten",
        "Die Liste nach Tags oder nach Notizen mit Aufgaben filtern",
    },
}

F["Oracle Search"] = { fp = "f8acda92",
    header = "Oracle-Suche",
    blurb = "Eine Suchleiste, mit der du von überall im Spiel aus jede Notiz anhand von Titel, Text oder Tag finden kannst. Öffne sie mit Strg+Leertaste oder /bnb search. Gib ? in die Leiste ein, um alle Möglichkeiten zum Eingrenzen der Suche zu sehen.",
    items = {
        "Eingabetaste öffnet die Notiz; Umschalt als Haftnotiz, Strg im Fokusmodus, Alt im Referenzbereich",
        "Präfixe: s Spielernotizen, n NPC-Notizen, i Gegenstände, z Zonen, a Aufgaben, e Alarme",
        "c dieser Charakter, g global, x formatiert, l einfacher Text, d heute / Woche / Monat",
        "b durchsucht den Papierkorb, o die Einstellungen, m sendet eine Notiz an den Chat",
        "#Tag, @Person, um die es in der Notiz geht, * Favoriten, -Wort zum Ausschließen eines Wortes, \"eine genaue Wortfolge\"",
    },
}

F["Tags"] = { fp = "71176c05",
    header = "Tags",
    blurb = "Tags sind kurze Stichwörter an einer Notiz, etwa Raid oder Gold. Du kannst einer Notiz beliebig viele geben; Groß- und Kleinschreibung spielt bei Tags keine Rolle.",
    items = {
        "Tags über das Rechtsklickmenü oder unter dem Titel im Editor hinzufügen",
        "Auf einen Tag klicken, um nur Notizen mit diesem Tag anzuzeigen",
        "Der Tag-Baum gruppiert alle Notizen nach Tags",
        "In der Tag-Verwaltung Tags für alle deine Notizen umbenennen, einfärben und löschen",
    },
}

